import{_ as e,c as t,o as a}from"./chunks/framework.B-xGQOFu.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"BTech ECE Syllabus NIT SILCHAR","text":"Complete ECE Syllabus","tagline":"Where every signal has noise -> and every lab has chaos."},"features":[{"icon":"🎯","title":"SEM 1","details":"What actually happens inside those tiny chips? We don’t fully know yet, but it probably involves a lot of voltage.","link":"/Syllabus/SEM1/"},{"icon":"🏗️","title":"SEM 2","details":"We finally made an LED blink! Not sure how… but it blinked, and that’s enough science for today.","link":"/Syllabu/SEM2/"},{"icon":"💻","title":"SEM 3","details":"Circuits make sense, until one resistor ruins the whole thing. Still figuring out what ‘ground’ actually means.","link":"/Syllabus/SEM3/"},{"icon":"🗄️","title":"SEM 4","details":"Signals and Systems sounded peaceful, turns out it’s just math with trust issues.","link":"/Syllabus/SEM4/"},{"icon":"🌐","title":"SEM 5","details":"Communication theory says noise is bad, but our lab’s full of it anyway. Trying to make sense of amplitude and attendance.","link":"/Syllabus/SEM5/"},{"icon":"☕","title":"SEM 6","details":"Microprocessors are fun, until the circuit refuses to run. We swear we connected the pins right... probably.","link":"/Syllabus/SEM6/"},{"icon":"⚡","title":"SEM 7","details":"We can finally design circuits… that almost work. Debugging both hardware and hope.","link":"/Syllabus/SEM7/"},{"icon":"📊","title":"SEM 8","details":"From signals to soldering, we learned everything, except how to fix the lab kit. Ready to connect to the real world.","link":"/Syllabus/SEM8/"}]},"headers":[],"relativePath":"branch/ece/index.md","filePath":"branch/ece/index.md"}'),i={name:"branch/ece/index.md"};function n(l,s,o,r,c,u){return a(),t("div")}const y=e(i,[["render",n]]);export{h as __pageData,y as default};
